using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class InventedGameChecks {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){var m=new InventedGameMemory();m.Confirm(false);m.Confirm(false);Require(!m.Discovered,"One/two experiments invented a game");m.Confirm(false);Require(m.Discovered&&m.Valid(),"Repeated safe experiments did not discover game");m.Retract(false);Require(!m.Discovered,"Late harm failed to retract discovery");m.invitations=1;m.Confirm(true);Require(m.replays==1&&m.Valid(),"Replay invalid");m.replays=9;Require(!m.Valid(),"Invented replay count accepted");var old=new SliceState();string before=JsonUtility.ToJson(old);CulturalBookText.Read(old,2,null);Require(before==JsonUtility.ToJson(old)&&old.worldPlay==null,"Reading invented old game history");Debug.Log("BWVR_INVENTED_GAME_MODEL_PASS");}
 public static void Verify(){
  Require(Application.isPlaying,"Enter Play mode");VerifyModel();var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var nav=god.GetComponent<IslandNavigator>();Require(!nav.world.TreeNavigationPending,"Wait for navigation");var site=god.GetComponent<CreatureConstructionLearning>().sites[0];var ball=slice.GetComponentInChildren<BeachBall>();var mind=god.GetComponent<CreatureCuriosity>();var people=slice.GetComponentsInChildren<VillagerSocial>();var positions=people.Select(p=>p.transform.position).ToArray();var field=typeof(QuestSlice).GetField("state",Flags);var original=field.GetValue(slice);var geometry=site.Capture();var recipe=site.Recipe;bool paused=site.Paused;var active=site.blocks.Select(b=>b.gameObject.activeSelf).ToArray();var physicsActive=site.blocks.Select(b=>b.Body.gameObject.activeSelf).ToArray();var gp=god.transform.position;var gr=god.transform.rotation;var cooldowns=god.Targets.Where(t=>t.affordance!=null).ToDictionary(t=>t.affordance,t=>t.affordance.cooldown);var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,hunger=.05f};test.Hybrid.time=100;var block=site.blocks.First(b=>b.Shape==ConstructionShape.Cube);var targetAt=new Vector3(0,block.size.y*.5f,0);
  void Arrange(){ball.ReturnHome();site.Paused=false;site.ResetConstruction();site.Recipe=BuildRecipe.Arch;for(int i=0;i<site.blocks.Count;i++){bool enabled=site.blocks[i]==block;site.blocks[i].gameObject.SetActive(enabled);site.blocks[i].Body.gameObject.SetActive(enabled);}Require(site.Drop(block,site.World(targetAt),site.transform.rotation),"Toy target failed to snap");}
  void Experiment(bool byCreature){Arrange();ball.transform.position=site.World(targetAt)-site.transform.right*nav.world.Scale*(ball.Radius+block.size.x*.5f+.8f);var at=ball.transform.position;at.y=site.transform.position.y+(ball.Radius+.05f)*nav.world.Scale;ball.transform.position=at;ball.Throw(site.transform.right,byCreature,24);ball.Body.linearVelocity=site.transform.right*24;for(int i=0;i<100&&block.Attached;i++){test.Hybrid.time+=.02f;ball.Advance(.02f,false);site.Advance(.02f);}Require(!block.Attached,"Native experiment did not topple snapped target");ball.FinishExperience();}
  try{
   god.Interrupt("Invented game QA");field.SetValue(slice,test);god.NewSeason();foreach(var p in people){p.ResetTask();p.GetComponent<VillagerExploration>().ResetTask();p.GetComponent<VillagerResourceGathering>().Cancel();p.GetComponent<VillagerBlockPlay>().ResetTask();p.transform.position+=Vector3.up*nav.world.Scale*500;}god.transform.position+=Vector3.up*nav.world.Scale*500;
   Experiment(false);Require(test.WorldPlay.invented==null,"Player knockdown taught creature discovery");for(int i=0;i<3;i++){Experiment(true);Require(test.WorldPlay.invented.safeKnockdowns==i+1,"Safe native experiment not recorded once");ball.FinishExperience();Require(test.WorldPlay.invented.safeKnockdowns==i+1,"Repeated finish duplicated discovery");}var memory=test.WorldPlay.invented;Require(memory.Discovered,"Three physical experiments did not discover knockdown play");
   var house=slice.GetComponentsInChildren<PlayImpactTarget>().First(t=>t.kind=="building");ball.Impact(house,24);Require(memory.safeKnockdowns==2&&!memory.Discovered,"Late harmful impact did not retract prior safe experiment");Experiment(true);Require(memory.Discovered,"Safe rediscovery failed");Arrange();Require(nav.world.Sample(site.World(new Vector3(-20,0,-4)),nav.profile,6,out var stage),"No replay stage");god.transform.position=nav.world.ProjectFoot(stage,nav.profile);god.transform.LookAt(new Vector3(block.transform.position.x,god.transform.position.y,block.transform.position.z));nav.ResetRoute();Require(ball.TryInventedAim(god.transform.position,out _),"Learned game could not find safe toy target");int safeCount=memory.safeKnockdowns;memory.safeKnockdowns=2;Require(!ball.TryInventedAim(god.transform.position,out _)&&ball.TryExperimentalAim(god.transform.position,out _),"Unlearned exploration requires an already invented rule");memory.safeKnockdowns=safeCount;
   site.Visitor=people[0].GetComponent<VillagerExploration>();Require(!ball.TryInventedAim(god.transform.position,out _),"Occupied yard targeted");site.Visitor=null;block.Item.held=true;Require(!ball.TryInventedAim(god.transform.position,out _),"Held target selected");block.Item.held=false;people[0].transform.position=Vector3.Lerp(god.transform.position,block.transform.position,.5f);Require(!ball.TryInventedAim(god.transform.position,out _),"Occupied roll corridor targeted");people[0].transform.position=positions[0]+Vector3.up*nav.world.Scale*500;test.paused=true;Require(!ball.TryInventedAim(god.transform.position,out _),"Paused game available");test.paused=false;
   test.Building.observed=15;ball.PlaceOnGround(nav.world.ProjectFoot(site.World(new Vector3(-19,0,-4)),nav.profile));foreach(var a in cooldowns.Keys)a.cooldown=a==ball.GetComponent<CreatureAffordance>()?0:test.Hybrid.time+1000;for(int serial=0;serial<100;serial++)if((CreatureDecisionModel.Variation(test.Hybrid.seed,serial,CreatureAction.PlayWithToy,"invented-knockdown")+1)*.5f<Mathf.Lerp(.2f,.9f,memory.preference)){test.Hybrid.decisions=serial;break;}
   Require(ball.TryInventedAim(god.transform.position,out _),"Replay lost safe aim after placement: flight="+ball.InFlight+" fetch="+ball.FetchReserved+" player="+ball.Player+" held="+ball.GetComponent<CarryItem>().held+" site pause="+site.Paused+" block kine="+block.Body.isKinematic+" god="+site.Local(god.transform.position)+" target="+block.Body.position);god.Perceive();Require(ball.GetComponent<CreatureAffordance>().Available,"Ball not available before replay: held="+ball.GetComponent<CarryItem>().held+" flight="+ball.InFlight+" fetch="+ball.FetchReserved);var ranked=(System.Collections.Generic.List<CreatureCandidate>)typeof(CreatureHybrid).GetField("candidates",Flags).GetValue(god);Require(ranked.Any(c=>c.target==ball.StableId&&c.action==CreatureAction.PlayWithToy),"Ball absent from ranked candidates: "+string.Join(" | ",ranked.Select(c=>c.target+"="+c.Score)));string firstRank=string.Join(" | ",ranked.Select(c=>c.target+"="+c.Score+" feasible="+c.feasible));bool chosen=false,beckoned=false;int replay=memory.replays;var hands=god.GetComponentInChildren<HumanoidHands>();for(int i=0;i<1600&&memory.replays==replay;i++){god.Tick(.05f);ball.Advance(.05f,false);site.Advance(.02f);chosen|=mind.PlayingInventedGame;beckoned|=hands!=null&&hands.beckon;}Require(chosen&&beckoned&&memory.invitations==1&&memory.replays==replay+1,"Native utility/carry/invite/roll failed: "+god.Explanation+" / "+mind.Current+" invites="+memory.invitations+" replays="+memory.replays+" initial ranking="+firstRank);for(int i=0;i<150&&god.Owner!=CreatureHybrid.ActionOwner.None;i++){god.Tick(.05f);ball.Advance(.05f,false);site.Advance(.02f);}Require(test.Hybrid.receipt.knockdown&&test.Hybrid.receipt.eligible,"Completed game did not create typed teaching receipt");float preference=memory.preference;Require(god.Feedback(true)&&memory.preference>preference&&!god.Feedback(false),"Contextual praise did not reinforce game once");Require(!ball.TryInventedAim(god.transform.position,out _),"Variety cooldown ignored");
   var saved=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(saved.Valid()&&saved.worldPlay.invented.Discovered&&CulturalBookText.Read(saved,2,null).text.Contains("discovered"),"Discovered rule/preferences did not save / read truthfully");saved.hybrid.receipt.goal=true;Require(!saved.Valid(),"Conflicting game lesson accepted");Debug.Log("BWVR_INVENTED_GAME_RUNTIME_PASS: actual safe creature-only physical discoveries, once-only/late-harm correction, occupied/held/corridor/pause gates, native utility-selected carry/beckon/roll, typed feedback, variety cooldown and persisted learned play");
  }finally{site.Visitor=null;god.Interrupt("Invented game QA complete");ball.ReturnHome();for(int i=0;i<site.blocks.Count;i++){site.blocks[i].Item.held=false;site.blocks[i].gameObject.SetActive(active[i]);site.blocks[i].Body.gameObject.SetActive(physicsActive[i]);}site.Recipe=recipe;site.Restore(geometry);site.Paused=paused;for(int i=0;i<people.Length;i++){people[i].transform.position=positions[i];people[i].GetComponent<IslandNavigator>().ResetRoute();}foreach(var a in cooldowns)a.Key.cooldown=a.Value;god.transform.SetPositionAndRotation(gp,gr);nav.ResetRoute();field.SetValue(slice,original);ball.ResetWorld();}
 }
}
}
